/* Route helper: sector name for a given mile */
export function sectorFor(mile) {
  let current = ROUTE[0];
  for (const stop of ROUTE) if (mile >= stop.mile) current = stop;
  return current;
}

export function nextStop(mile) {
  return ROUTE.find((s) => s.mile > mile) || ROUTE[ROUTE.length - 1];
}

/* ASH TRAIL — encounter deck */

const has = (g, cost) => {
  for (const [k, v] of Object.entries(cost)) if ((g.s[k] || 0) < v) return false;
  return true;
};
const need = (cost) => (g) => (has(g, cost) ? null : 'Not enough ' + Object.keys(cost).join(' / '));

