/* ASH TRAIL — wasteland canvas renderer */

const TAU = Math.PI * 2;
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const SKIES = {
  dusk:  { top: '#0a0c14', mid: '#2a1b16', low: '#7a3f1e', glow: '#ff9a45', sun: '#ffcf8e' },
  haze:  { top: '#14100e', mid: '#3a2a1e', low: '#8a5a30', glow: '#d9964c', sun: '#e8b57a' },
  dust:  { top: '#1b130d', mid: '#4a2f19', low: '#a06430', glow: '#e2a04a', sun: '#f0c084' },
  storm: { top: '#0b0b0f', mid: '#232126', low: '#4a4040', glow: '#8a6a4a', sun: '#a89380' },
  rain:  { top: '#080e11', mid: '#16282c', low: '#2c4a4a', glow: '#5f8f8a', sun: '#9fc0b8' },
  cold:  { top: '#060b12', mid: '#152333', low: '#33505f', glow: '#7fa8b8', sun: '#cfe0e4' },
};

export class WastelandScene {
  constructor(canvas, opts = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.title = !!opts.title;
    this.state = { mile: 0, weather: 'clear', pace: 'steady', hull: 84, progress: 0 };
    this.scroll = 0;
    this.speed = 0;
    this.targetSpeed = this.title ? 0.25 : 0.55;
    this.time = 0;
    this.shake = 0;
    this.running = false;
    this.particles = [];
    this.dust = [];
    this.buildings = [];
    this.midProps = [];
    this.stars = [];
    this.rocks = [];
    this.last = 0;
    this.resizeObserver = null;
    this._seeded();
    this._resize();
    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => this._resize());
      this.resizeObserver.observe(canvas.parentElement || canvas);
    } else {
      window.addEventListener('resize', () => this._resize());
    }
    this._raf = this._raf.bind(this);
  }

  _seeded() {
    const r1 = mulberry32(99173);
    this.buildings = [];
    let x = 0;
    while (x < 1600) {
      const w = 14 + r1() * 60;
      const h = 20 + r1() * 130;
      this.buildings.push({ x, w, h, seed: r1(), broken: r1() > 0.45, antenna: r1() > 0.72, lights: r1() });
      x += w + 3 + r1() * 20;
    }
    this.skylineWidth = x;
    const r2 = mulberry32(4421);
    this.midProps = [];
    let mx = 0;
    while (mx < 1400) {
      const t = r2();
      this.midProps.push({ x: mx, type: t > 0.55 ? 'pylon' : t > 0.3 ? 'ruin' : 'tower', s: 0.6 + r2() * 0.8, seed: r2() });
      mx += 110 + r2() * 150;
    }
    this.midWidth = mx;
    const r3 = mulberry32(8821);
    this.stars = Array.from({ length: 80 }, () => ({ x: r3(), y: r3() * 0.55, s: 0.4 + r3() * 1.1, p: r3() * TAU }));
    this.rocks = Array.from({ length: 46 }, () => ({ x: r3(), s: 0.3 + r3() * 1.1, t: r3() }));
    this.dustSeeds = Array.from({ length: 30 }, () => ({ x: r3(), y: r3(), s: 0.4 + r3() * 1.6, v: 0.2 + r3() * 0.8 }));
    this.rainSeeds = Array.from({ length: 70 }, () => ({ x: r3(), y: r3(), v: 0.6 + r3() * 0.8, l: 6 + r3() * 16 }));
  }

  setState(patch) {
    Object.assign(this.state, patch);
  }

  setSpeed(v) { this.targetSpeed = v; }

  kick(amount = 1) { this.shake = Math.min(18, this.shake + amount * 5); }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    requestAnimationFrame(this._raf);
  }

  stop() { this.running = false; }

  _resize() {
    const el = this.canvas;
    const rect = el.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    el.width = Math.round(rect.width * dpr);
    el.height = Math.round(rect.height * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.w = rect.width;
    this.h = rect.height;
    this.dpr = dpr;
  }

  _raf(now) {
    if (!this.running) return;
    const dt = Math.min(0.05, (now - this.last) / 1000 || 0.016);
    this.last = now;
    this._update(dt);
    this._draw();
    requestAnimationFrame(this._raf);
  }

  _update(dt) {
    this.time += dt;
    this.speed += (this.targetSpeed - this.speed) * Math.min(1, dt * 2.6);
    if (this.title) this.speed = 0.22 + Math.sin(this.time * 0.4) * 0.05;
    this.scroll += this.speed * dt * 160;
    this.shake *= Math.pow(0.0015, dt);
    const weather = this.state.weather || 'clear';

    if (this.speed > 0.12 && !this.title) {
      const wheelX = this.w * (this.w > 700 ? 0.42 : 0.46);
      const wheelY = this._roadY() + this._vh() * 0.1;
      const n = weather === 'storm' || weather === 'dust' ? 3 : 2;
      for (let i = 0; i < n; i++) {
        if (Math.random() < 0.55) {
          this.dust.push({
            x: wheelX - this._vh() * (0.7 + Math.random() * 0.5),
            y: wheelY + (Math.random() - 0.4) * 8,
            vx: -20 - Math.random() * 60 * this.speed,
            vy: -4 - Math.random() * 16,
            r: 2 + Math.random() * 5,
            life: 0,
            max: 0.7 + Math.random() * 1.1,
          });
        }
      }
    }
    for (let i = this.dust.length - 1; i >= 0; i--) {
      const p = this.dust[i];
      p.life += dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= 0.98;
      p.r += dt * 5;
      if (p.life > p.max) this.dust.splice(i, 1);
    }
  }

  _sunY() { return this.h * (this.title ? 0.5 : 0.52); }
  _horizon() { return this.h * (this.title ? 0.6 : 0.62); }
  _roadY() { return this.h * (this.title ? 0.8 : 0.84); }
  _vh() { return clamp(this.h * (this.title ? 0.2 : 0.24), 30, 150); }

  _draw() {
    const { ctx, w, h } = this;
    if (!w || !h) return;
    const weather = this.state.weather || 'clear';
    const sky = SKIES[weather] || SKIES.dusk;
    ctx.save();
    if (this.shake > 0.2) ctx.translate((Math.random() - 0.5) * this.shake, (Math.random() - 0.5) * this.shake);
    this._sky(sky, weather);
    this._sun(sky, weather);
    this._stars(weather);
    this._skyline(sky);
    this._ground(sky);
    this._midground(sky);
    this._foreground();
    this._crawler(weather);
    this._weatherFx(weather);
    this._vignette();
    ctx.restore();
  }

  _sky(sky, weather) {
    const { ctx, w, h } = this;
    const horizon = this._horizon();
    const g = ctx.createLinearGradient(0, 0, 0, horizon);
    g.addColorStop(0, sky.top);
    g.addColorStop(0.55, sky.mid);
    g.addColorStop(1, sky.low);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, horizon + 2);

    // haze bands near horizon
    for (let i = 0; i < 7; i++) {
      const y = horizon - 8 - i * (horizon * 0.055);
      ctx.fillStyle = `rgba(255,170,90,${0.035 + i * 0.004})`;
      ctx.fillRect(0, y, w, 1.5 + i * 0.4);
    }

    // green shimmer of Eden near the end
    const prog = this.state.mile / 960;
    if (prog > 0.72) {
      const a = (prog - 0.72) / 0.28;
      const rg = ctx.createRadialGradient(w * 0.62, horizon - 4, 2, w * 0.62, horizon - 4, w * 0.3);
      rg.addColorStop(0, `rgba(120,220,170,${0.2 * a})`);
      rg.addColorStop(1, 'rgba(120,220,170,0)');
      ctx.fillStyle = rg;
      ctx.fillRect(w * 0.3, 0, w * 0.66, horizon);
    }
  }

  _sun(sky, weather) {
    const { ctx, w, h } = this;
    const x = w * (this.title ? 0.58 : 0.7);
    const y = this._sunY();
    const r = Math.max(18, h * (this.title ? 0.1 : 0.075));
    const glow = ctx.createRadialGradient(x, y, r * 0.3, x, y, r * 5.5);
    glow.addColorStop(0, this._alpha(sky.glow, 0.5));
    glow.addColorStop(0.28, this._alpha(sky.glow, 0.18));
    glow.addColorStop(1, this._alpha(sky.glow, 0));
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, w, this._horizon());
    ctx.fillStyle = this._alpha(sky.sun, weather === 'storm' || weather === 'rain' ? 0.35 : 0.9);
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
    // scan-sun slats
    ctx.fillStyle = this._alpha(sky.mid, 0.55);
    for (let i = 0; i < 4; i++) {
      const sy = y + r * 0.05 + i * (r * 0.28);
      ctx.fillRect(x - r * 1.1, sy, r * 2.2, r * 0.075);
    }
  }

  _alpha(hex, a) {
    const v = hex.replace('#', '');
    const n = parseInt(v, 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
  }

  _stars(weather) {
    if (weather === 'dust' || weather === 'storm' || weather === 'rain' || weather === 'haze' || this.title) return;
    const { ctx, w, h } = this;
    for (const s of this.stars) {
      const tw = 0.35 + Math.sin(this.time * 1.6 + s.p) * 0.3;
      ctx.fillStyle = `rgba(210,225,255,${0.28 * tw})`;
      ctx.fillRect(s.x * w, s.y * this._horizon() * 0.85, s.s, s.s);
    }
  }

  _skyline(sky) {
    const { ctx, w, h } = this;
    const horizon = this._horizon();
    const off = (this.scroll * 0.06) % this.skylineWidth;
    const baseFill = this._mix('#161210', sky.mid, 0.25);
    for (let pass = 0; pass < 2; pass++) {
      const baseX = -off + pass * this.skylineWidth;
      if (baseX > w) continue;
      for (const b of this.buildings) {
        const x = baseX + b.x;
        if (x > w + 80 || x + b.w < -80) continue;
        const bh = (b.h / 160) * (h * 0.3);
        const top = horizon - bh;
        ctx.fillStyle = baseFill;
        ctx.beginPath();
        if (b.broken) {
          ctx.moveTo(x, horizon);
          ctx.lineTo(x, top + bh * 0.35);
          ctx.lineTo(x + b.w * 0.28, top + bh * 0.2);
          ctx.lineTo(x + b.w * 0.4, top + bh * 0.42);
          ctx.lineTo(x + b.w * 0.72, top);
          ctx.lineTo(x + b.w, top + bh * 0.3);
          ctx.lineTo(x + b.w, horizon);
        } else {
          ctx.rect(x, top, b.w, bh);
        }
        ctx.fill();
        if (b.antenna) {
          ctx.fillRect(x + b.w * 0.5, top - bh * 0.16, 1.2, bh * 0.17);
          ctx.fillStyle = 'rgba(255,90,70,.5)';
          ctx.fillRect(x + b.w * 0.5 - 1, top - bh * 0.17, 2.4, 2);
        }
        if (b.lights > 0.35) {
          ctx.fillStyle = `rgba(255,180,90,${0.06 + b.lights * 0.12})`;
          for (let wy = 0; wy < 4; wy++) {
            for (let wx = 0; wx < 3; wx++) {
              if ((wx + wy + b.seed * 9) % 3 < 1.2) continue;
              ctx.fillRect(x + 3 + wx * (b.w / 4), top + 6 + wy * (bh / 6), 2, 2.4);
            }
          }
        }
      }
    }
    // haze layer over the city
    const hz = ctx.createLinearGradient(0, horizon - h * 0.12, 0, horizon + 2);
    hz.addColorStop(0, this._alpha(sky.low, 0));
    hz.addColorStop(1, this._alpha(sky.low, 0.5));
    ctx.fillStyle = hz;
    ctx.fillRect(0, horizon - h * 0.12, w, h * 0.12 + 2);
  }

  _mix(a, b, t) {
    const pa = parseInt(a.replace('#', ''), 16);
    const pb = parseInt(b.replace('#', ''), 16);
    const r = Math.round((((pa >> 16) & 255) * (1 - t) + ((pb >> 16) & 255) * t));
    const g = Math.round((((pa >> 8) & 255) * (1 - t) + ((pb >> 8) & 255) * t));
    const bl = Math.round(((pa & 255) * (1 - t) + (pb & 255) * t));
    return `rgb(${r},${g},${bl})`;
  }

  _ground(sky) {
    const { ctx, w, h } = this;
    const horizon = this._horizon();
    const g = ctx.createLinearGradient(0, horizon, 0, h);
    g.addColorStop(0, this._mix('#0e0b09', sky.mid, 0.2));
    g.addColorStop(0.35, '#0d0b09');
    g.addColorStop(1, '#080706');
    ctx.fillStyle = g;
    ctx.fillRect(0, horizon, w, h - horizon);
    const road = this._roadY();
    // road surface
    const rg = ctx.createLinearGradient(0, road, 0, h);
    rg.addColorStop(0, '#1a1714');
    rg.addColorStop(1, '#0b0908');
    ctx.fillStyle = rg;
    ctx.fillRect(0, road, w, h - road);
    // road edge
    ctx.fillStyle = 'rgba(232,221,200,.09)';
    ctx.fillRect(0, road, w, 1);
    // center dashes
    const spacing = Math.max(48, w * 0.075);
    const dashOff = this.scroll % spacing;
    const dy = road + (h - road) * 0.52;
    ctx.fillStyle = 'rgba(220,200,160,.16)';
    for (let x = -spacing; x < w + spacing; x += spacing) {
      ctx.fillRect(x - dashOff, dy, spacing * 0.34, 2.2);
    }
    // cracks
    ctx.strokeStyle = 'rgba(0,0,0,.5)';
    ctx.lineWidth = 1;
    const r = mulberry32(77);
    for (let i = 0; i < 8; i++) {
      const cx = ((r() * w + this.scroll * 0.9) % (w + 80)) - 40;
      const cy = road + (h - road) * (0.25 + r() * 0.65);
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + 12, cy + 2);
      ctx.lineTo(cx + 22, cy - 2);
      ctx.stroke();
    }
  }

  _midground(sky) {
    const { ctx, w, h } = this;
    const horizon = this._horizon();
    const off = (this.scroll * 0.22) % this.midWidth;
    const fill = this._mix('#110e0c', sky.mid, 0.18);
    for (let pass = 0; pass < 2; pass++) {
      const baseX = -off + pass * this.midWidth;
      if (baseX > w) continue;
      for (const p of this.midProps) {
        const x = baseX + p.x;
        if (x > w + 140 || x < -140) continue;
        const s = p.s * (h / 500);
        ctx.fillStyle = fill;
        if (p.type === 'pylon') {
          const ph = 90 * s;
          ctx.beginPath();
          ctx.moveTo(x - 12 * s, horizon);
          ctx.lineTo(x - 3 * s, horizon - ph);
          ctx.lineTo(x + 3 * s, horizon - ph);
          ctx.lineTo(x + 12 * s, horizon);
          ctx.closePath();
          ctx.fill();
          for (let i = 1; i < 4; i++) {
            const yy = horizon - ph * (i / 4);
            const ww = (10 - i * 2) * s;
            ctx.fillRect(x - ww, yy, ww * 2, 1.4 * s + 0.6);
          }
          ctx.strokeStyle = 'rgba(232,221,200,.07)';
          ctx.beginPath();
          ctx.moveTo(x, horizon - ph);
          ctx.quadraticCurveTo(x + 60 * s, horizon - ph + 18 * s, x + 120 * s, horizon - ph + 8 * s);
          ctx.stroke();
        } else if (p.type === 'ruin') {
          const bw = 60 * s, bh = 46 * s;
          ctx.fillRect(x - bw / 2, horizon - bh, bw, bh);
          ctx.fillRect(x - bw / 2, horizon - bh, bw * 0.26, bh * 0.5);
          ctx.fillRect(x + bw * 0.12, horizon - bh * 1.3, bw * 0.24, bh * 0.32);
          ctx.fillStyle = 'rgba(255,180,90,.12)';
          ctx.fillRect(x + 4 * s, horizon - bh * 0.6, 3 * s, 4 * s);
        } else {
          const tw = 40 * s, th = 110 * s;
          ctx.fillRect(x - tw * 0.18, horizon - th, tw * 0.36, th);
          ctx.fillRect(x - tw * 0.5, horizon - th * 0.86, tw, th * 0.06);
          ctx.beginPath();
          ctx.arc(x, horizon - th * 0.86, tw * 0.42, Math.PI, 0);
          ctx.fill();
          ctx.fillRect(x - tw * 0.5, horizon - th * 0.6, tw, 1.6);
        }
      }
    }
    // dark ridge in front of props
    ctx.fillStyle = '#0c0a08';
    ctx.beginPath();
    ctx.moveTo(0, horizon + 11);
    const step = Math.max(30, w / 22);
    const r = mulberry32(311);
    for (let x = 0; x <= w + step; x += step) {
      ctx.lineTo(x, horizon + 6 + (r() - 0.5) * 9);
    }
    ctx.lineTo(w, horizon + 22);
    ctx.lineTo(0, horizon + 22);
    ctx.closePath();
    ctx.fill();
  }

  _foreground() {
    const { ctx, w, h } = this;
    const road = this._roadY();
    // fast roadside debris
    for (const rock of this.rocks) {
      const speed = this.scroll * (1.5 + rock.s * 0.6);
      const x = ((rock.x * (w + 160) - speed) % (w + 160) + (w + 160)) % (w + 160) - 80;
      const y = road + (h - road) * (0.18 + rock.t * 0.3);
      const s = rock.s * (h / 700);
      ctx.fillStyle = 'rgba(12,10,8,.9)';
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + 12 * s, y - 5 * s);
      ctx.lineTo(x + 20 * s, y + 1 * s);
      ctx.lineTo(x + 7 * s, y + 3 * s);
      ctx.closePath();
      ctx.fill();
    }
    // kilometer sign on the shoulder
    const signX = w * 0.82;
    const signY = road - 14;
    ctx.strokeStyle = '#2a2620';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(signX, signY);
    ctx.lineTo(signX, signY + (h - road) * 0.38);
    ctx.stroke();
    ctx.fillStyle = '#232019';
    ctx.fillRect(signX - 13, signY - 20, 26, 16);
    ctx.fillStyle = 'rgba(255,180,84,.5)';
    ctx.font = '8px ui-monospace, monospace';
    ctx.textAlign = 'center';
    ctx.fillText('E9', signX, signY - 8);
    ctx.textAlign = 'left';
  }

  _crawler(weather) {
    const { ctx, w, h } = this;
    const road = this._roadY();
    const vh = this._vh();
    const x = w * (this.title ? 0.5 : w > 700 ? 0.43 : 0.46);
    const y = road + (h - road) * 0.5;
    const bob = Math.sin(this.time * 7) * this.speed * 1.4 + Math.sin(this.time * 1.7) * 0.6;
    ctx.save();
    ctx.translate(x, y + bob);

    // shadow
    const sh = ctx.createRadialGradient(0, vh * 0.42, 2, 0, vh * 0.42, vh * 1.5);
    sh.addColorStop(0, 'rgba(0,0,0,.6)');
    sh.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = sh;
    ctx.beginPath();
    ctx.ellipse(0, vh * 0.45, vh * 1.5, vh * 0.28, 0, 0, TAU);
    ctx.fill();

    // headlight cone
    const beam = ctx.createLinearGradient(vh * 0.8, 0, vh * 3.4, 0);
    beam.addColorStop(0, 'rgba(255,200,120,.22)');
    beam.addColorStop(1, 'rgba(255,200,120,0)');
    ctx.fillStyle = beam;
    ctx.beginPath();
    ctx.moveTo(vh * 0.78, -vh * 0.05);
    ctx.lineTo(vh * 3.6, -vh * 0.5);
    ctx.lineTo(vh * 3.6, vh * 0.4);
    ctx.lineTo(vh * 0.78, vh * 0.12);
    ctx.closePath();
    ctx.fill();

    // wheels
    const wheelR = vh * 0.21;
    const wheelY = vh * 0.24;
    const wheelXs = [-vh * 0.62, 0, vh * 0.62];
    for (const wx of wheelXs) {
      ctx.fillStyle = '#141110';
      ctx.beginPath();
      ctx.arc(wx, wheelY, wheelR, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = 'rgba(232,221,200,.12)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.save();
      ctx.translate(wx, wheelY);
      ctx.rotate(-this.scroll * 0.055);
      ctx.fillStyle = '#3a332c';
      for (let i = 0; i < 4; i++) {
        ctx.rotate(Math.PI / 2);
        ctx.fillRect(-1.4, -wheelR * 0.72, 2.8, wheelR * 1.44);
      }
      ctx.fillStyle = '#0b0908';
      ctx.beginPath();
      ctx.arc(0, 0, wheelR * 0.34, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // undercarriage
    ctx.fillStyle = '#17130f';
    ctx.fillRect(-vh * 0.92, vh * 0.02, vh * 1.84, vh * 0.2);

    // main body
    const bodyG = ctx.createLinearGradient(0, -vh * 0.6, 0, vh * 0.25);
    bodyG.addColorStop(0, '#4a3f34');
    bodyG.addColorStop(0.45, '#332b24');
    bodyG.addColorStop(1, '#221c17');
    ctx.fillStyle = bodyG;
    ctx.beginPath();
    const bw = vh * 1.86;
    const bh = vh * 0.56;
    const top = -vh * 0.46;
    const rr = vh * 0.06;
    ctx.moveTo(-bw / 2 + rr, top);
    ctx.lineTo(bw / 2 - vh * 0.28, top);
    ctx.lineTo(bw / 2, top + vh * 0.18);
    ctx.lineTo(bw / 2, top + bh);
    ctx.lineTo(-bw / 2, top + bh);
    ctx.lineTo(-bw / 2, top + rr);
    ctx.quadraticCurveTo(-bw / 2, top, -bw / 2 + rr, top);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,190,120,.18)';
    ctx.lineWidth = 1;
    ctx.stroke();

    // rust/panel streaks
    ctx.strokeStyle = 'rgba(140,80,40,.35)';
    ctx.lineWidth = 1.4;
    const rr2 = mulberry32(55);
    for (let i = 0; i < 5; i++) {
      const px = -vh * 0.8 + rr2() * vh * 1.5;
      ctx.beginPath();
      ctx.moveTo(px, top + vh * 0.06);
      ctx.lineTo(px + 2, top + bh * (0.4 + rr2() * 0.5));
      ctx.stroke();
    }

    // cabin window
    const wx = -vh * 0.6;
    const wy = top + vh * 0.1;
    const ww = vh * 0.56;
    const wh = vh * 0.24;
    const winG = ctx.createLinearGradient(wx, wy, wx + ww, wy + wh);
    winG.addColorStop(0, 'rgba(130,220,205,.55)');
    winG.addColorStop(1, 'rgba(40,90,90,.35)');
    ctx.fillStyle = winG;
    ctx.beginPath();
    ctx.moveTo(wx, wy + wh);
    ctx.lineTo(wx, wy + 4);
    ctx.quadraticCurveTo(wx, wy, wx + 5, wy);
    ctx.lineTo(wx + ww - 6, wy);
    ctx.quadraticCurveTo(wx + ww, wy, wx + ww, wy + 5);
    ctx.lineTo(wx + ww, wy + wh);
    ctx.closePath();
    ctx.fill();
    // driver silhouette
    ctx.fillStyle = 'rgba(10,14,14,.72)';
    ctx.beginPath();
    ctx.arc(wx + ww * 0.36, wy + wh * 0.45, wh * 0.24, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(wx + ww * 0.36, wy + wh * 1.05, wh * 0.42, wh * 0.55, 0, Math.PI, TAU);
    ctx.fill();
    // window reflection
    ctx.fillStyle = 'rgba(255,255,255,.09)';
    ctx.beginPath();
    ctx.moveTo(wx + 4, wy + wh);
    ctx.lineTo(wx + ww * 0.55, wy);
    ctx.lineTo(wx + ww * 0.72, wy);
    ctx.lineTo(wx + ww * 0.18, wy + wh);
    ctx.closePath();
    ctx.fill();

    // roof cargo
    ctx.fillStyle = '#2a241e';
    ctx.fillRect(-vh * 0.5, top - vh * 0.18, vh * 0.7, vh * 0.18);
    ctx.fillStyle = '#39312a';
    ctx.fillRect(-vh * 0.46, top - vh * 0.25, vh * 0.3, vh * 0.09);
    ctx.fillRect(vh * 0.02, top - vh * 0.23, vh * 0.22, vh * 0.07);
    ctx.strokeStyle = 'rgba(20,16,12,.9)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(-vh * 0.38, top - vh * 0.26);
    ctx.lineTo(-vh * 0.38, top);
    ctx.moveTo(vh * 0.08, top - vh * 0.25);
    ctx.lineTo(vh * 0.08, top);
    ctx.stroke();

    // antenna
    ctx.strokeStyle = '#4a4238';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(vh * 0.62, top);
    ctx.lineTo(vh * 0.72, top - vh * 0.55);
    ctx.stroke();
    const blink = Math.sin(this.time * 3.2) > 0.2;
    if (blink) {
      ctx.fillStyle = 'rgba(255,80,60,.9)';
      ctx.beginPath();
      ctx.arc(vh * 0.72, top - vh * 0.55, 1.8, 0, TAU);
      ctx.fill();
    }

    // headlight
    ctx.fillStyle = '#ffe2ae';
    ctx.shadowColor = 'rgba(255,190,110,.9)';
    ctx.shadowBlur = 14;
    ctx.beginPath();
    ctx.arc(vh * 0.86, top + vh * 0.3, vh * 0.035, 0, TAU);
    ctx.fill();
    ctx.shadowBlur = 0;

    // grille
    ctx.strokeStyle = 'rgba(10,8,7,.8)';
    ctx.lineWidth = 1.6;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(vh * 0.7 + i * vh * 0.06, top + vh * 0.24);
      ctx.lineTo(vh * 0.7 + i * vh * 0.06, top + vh * 0.4);
      ctx.stroke();
    }

    // damage
    const hull = this.state.hull ?? 84;
    if (hull < 55) {
      ctx.strokeStyle = 'rgba(255,90,60,.5)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(-vh * 0.3, top + vh * 0.02);
      ctx.lineTo(-vh * 0.18, top + vh * 0.14);
      ctx.lineTo(-vh * 0.24, top + vh * 0.22);
      ctx.stroke();
    }
    if (hull < 35) {
      for (let i = 0; i < 3; i++) {
        const t = (this.time * 0.5 + i * 0.33) % 1;
        ctx.fillStyle = `rgba(40,36,32,${0.32 * (1 - t)})`;
        ctx.beginPath();
        ctx.arc(-vh * 0.8 - t * vh * 0.7, top - t * vh * 0.8, 3 + t * vh * 0.18, 0, TAU);
        ctx.fill();
      }
    }

    ctx.restore();

    // dust puffs
    for (const p of this.dust) {
      const a = Math.max(0, 1 - p.life / p.max) * 0.22;
      ctx.fillStyle = `rgba(150,115,80,${a})`;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, TAU);
      ctx.fill();
    }
  }

  _weatherFx(weather) {
    const { ctx, w, h } = this;
    if (weather === 'rain') {
      ctx.strokeStyle = 'rgba(170,210,205,.25)';
      ctx.lineWidth = 1;
      for (const s of this.rainSeeds) {
        const y = ((s.y * h + this.time * 420 * s.v) % (h + 40)) - 20;
        const x = ((s.x * w - this.time * 90 * s.v + this.scroll * 0.2) % (w + 40) + w + 40) % (w + 40) - 20;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x - 3, y + s.l);
        ctx.stroke();
      }
    } else if (weather === 'dust' || weather === 'storm') {
      const alpha = weather === 'storm' ? 0.4 : 0.25;
      ctx.fillStyle = weather === 'storm' ? 'rgba(90,70,55,.22)' : 'rgba(160,110,55,.12)';
      ctx.fillRect(0, 0, w, h);
      for (const s of this.dustSeeds) {
        const speed = (weather === 'storm' ? 260 : 120) * s.v;
        const x = ((s.x * w + this.time * speed) % (w + 60)) - 30;
        const y = (s.y * h + Math.sin(this.time * 0.7 + s.x * 10) * 12) % h;
        ctx.fillStyle = `rgba(220,180,130,${alpha * 0.35})`;
        ctx.fillRect(x, y, s.s * 7, 1);
      }
    } else if (weather === 'cold') {
      for (const s of this.dustSeeds) {
        const x = ((s.x * w + this.time * 16 * s.v) % (w + 20)) - 10;
        const y = ((s.y * h + this.time * 30 * s.v) % (h + 20)) - 10;
        ctx.fillStyle = 'rgba(220,235,240,.18)';
        ctx.fillRect(x, y, 1.4, 1.4);
      }
    }
    // global haze tint
    if (weather === 'haze') {
      ctx.fillStyle = 'rgba(255,150,70,.05)';
      ctx.fillRect(0, 0, w, h);
    }
  }

  _vignette() {
    const { ctx, w, h } = this;
    const g = ctx.createRadialGradient(w * 0.5, h * 0.55, Math.min(w, h) * 0.25, w * 0.5, h * 0.55, Math.max(w, h) * 0.78);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(1, 'rgba(0,0,0,.55)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  }
}

/* ASH TRAIL — game rules and state */

import { START, CREW_TEMPLATES, ROUTE, PACES, RATIONS, BASE_USE, WEATHERS, CHORES } from './data.js';
import { EVENTS, AMBIENT, ROAD_RUMORS } from './events.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
const int = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const chance = (p) => Math.random() < p;
const SAVE_KEY = 'ashtrail-run-v1';

const START_LOG = [
  ['The Lastlight gate closes behind you. It does not open again.', 'daybreak'],
  ['Four survivors. One crawler. Nine hundred sixty miles to a rumor.', ''],
  ['Mara checks the welds. Imani checks the water. Dex checks the locks. Rook checks the horizon, then checks it again.', ''],
  ['Eden-9 or nothing. Drive.', 'good'],
];

export class Game {
  constructor() {
    this.S = null;
    this.phase = 'menu';
    this.pendingEvent = null;
    this.pendingArrival = null;
    this.lastResult = null;
  }

  /* ---------- lifecycle ---------- */

  newGame() {
    const crew = CREW_TEMPLATES.map((c) => ({
      id: c.id, name: c.name, role: c.role, initials: c.initials, tone: c.tone,
      trait: c.trait, perk: c.perk, health: c.health, status: 'ok', alive: true, cause: null,
    }));
    const stocks = {};
    for (const stop of ROUTE) stocks[stop.mile] = { ...stop.stock };
    this.S = {
      version: 1,
      day: 1, mile: 0,
      water: START.water, food: START.food, fuel: START.fuel, scrap: START.scrap, meds: START.meds,
      hull: START.hull, morale: START.morale,
      pace: 'steady', ration: 'half', weather: 'clear',
      party: crew, stocks,
      visited: [0], restedAt: [], rumors: {}, recentEvents: [],
      stats: { chores: 0, events: 0, miles: 0, scavenged: 0, damages: 0 },
      log: START_LOG.map(([text, kind]) => ({ day: 1, text, kind })),
      ended: null, dog: false,
      scrapEarned: 0, foodFound: 0,
    };
    this.phase = 'travel';
    this.pendingEvent = null;
    this.pendingArrival = null;
    return this.snapshot();
  }

  snapshot() {
    return {
      state: this.S, phase: this.phase,
      event: this.pendingEvent, arrival: this.pendingArrival, ended: this.S?.ended || null,
    };
  }

  save() {
    try { if (this.S) localStorage.setItem(SAVE_KEY, JSON.stringify(this.S)); } catch { /* storage may be unavailable */ }
  }

  hasSave() {
    try { return !!localStorage.getItem(SAVE_KEY); } catch { return false; }
  }

  load() {
    try {
      const raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return null;
      const S = JSON.parse(raw);
      if (!S || !Array.isArray(S.party) || S.version !== 1) return null;
      this.S = S;
      this.phase = S.ended ? 'ended' : 'travel';
      this.pendingEvent = null;
      this.pendingArrival = null;
      return this.snapshot();
    } catch { return null; }
  }

  clearSave() {
    try { localStorage.removeItem(SAVE_KEY); } catch { /* ignore */ }
  }

  alive() { return this.S.party.filter((p) => p.alive); }
  aliveCount() { return this.alive().length; }
  hasTrait(id) { return this.S.party.some((p) => p.alive && p.id === id); }
  getStop(mile = this.S.mile) { return ROUTE.find((s) => s.mile === mile) || ROUTE[0]; }
  nextStop() { return ROUTE.find((s) => s.mile > this.S.mile) || null; }

  /* ---------- resources ---------- */

  log(text, kind = '') {
    this.S.log.push({ day: this.S.day, text, kind });
    if (this.S.log.length > 120) this.S.log.splice(0, this.S.log.length - 120);
  }

  add(delta) {
    const S = this.S;
    if (delta.water != null) S.water = clamp(S.water + delta.water, 0, 99);
    if (delta.food != null) S.food = clamp(S.food + delta.food, 0, 99);
    if (delta.fuel != null) S.fuel = clamp(S.fuel + delta.fuel, 0, 99);
    if (delta.scrap != null) S.scrap = clamp(S.scrap + delta.scrap, 0, 9999);
    if (delta.meds != null) S.meds = clamp(S.meds + delta.meds, 0, 99);
    if (delta.hull != null) S.hull = clamp(S.hull + delta.hull, 0, 100);
    if (delta.morale != null) S.morale = clamp(S.morale + delta.morale, 0, 100);
    if (delta.mile != null) S.mile = Math.max(0, Math.min(960, S.mile + delta.mile));
    if (delta.scrap > 0) S.scrapEarned += delta.scrap;
  }

  pay(cost) {
    for (const k of Object.keys(cost)) {
      if ((this.S[k] || 0) < cost[k]) return false;
    }
    for (const k of Object.keys(cost)) this.S[k] -= cost[k];
    return true;
  }

  canAfford(cost) {
    return Object.entries(cost).every(([k, v]) => (this.S[k] || 0) >= v);
  }

  health(member, amount, status, cause) {
    if (!member || !member.alive) return member;
    const soften = this.hasTrait('rook') ? 0.88 : 1;
    if (amount < 0) amount *= soften;
    member.health = clamp(member.health + amount, 0, 100);
    if (status && member.health > 0) {
      const bad = ['sick', 'injured', 'rad'];
      if (bad.includes(status)) member.status = status;
    }
    if (member.health <= 0) {
      member.alive = false;
      member.health = 0;
      member.status = 'dead';
      this.log(`${member.name} is dead. ${cause || pick(['The road took them.', 'There was nothing left to do.', 'It was quick, at least.'])}`, 'bad');
    }
    return member;
  }

  hurt(amount, status = 'injured', member = null) {
    const target = member && member.alive ? member : pick(this.alive());
    if (!target) return null;
    this.health(target, -amount, status);
    return target;
  }

  hurtAll(amount, status = 'injured') {
    for (const p of this.alive()) this.health(p, -amount, status);
  }

  heal(amount, member = null) {
    const targets = member ? [member] : this.alive();
    for (const p of targets) {
      if (!p.alive) continue;
      const bonus = this.hasTrait('reyes') ? 1.55 : 1;
      p.health = clamp(p.health + amount * bonus, 0, 100);
      if (p.health > 32) p.status = 'ok';
    }
  }

  byId(id) { return this.S.party.find((p) => p.id === id); }

  /* ---------- day / weather / travel ---------- */

  rollWeather() {
    const prev = this.S.weather;
    const table = [
      ['clear', 0.34], ['haze', 0.24], ['dust', 0.17], ['storm', 0.07], ['rain', 0.11], ['cold', 0.07],
    ];
    if (prev === 'dust') { table[2][1] += 0.08; table[3][1] += 0.06; table[0][1] -= 0.06; }
    if (prev === 'storm') { table[3][1] = 0; table[1][1] += 0.1; }
    if (prev === 'rain') { table[4][1] = 0.02; table[1][1] += 0.08; }
    const total = table.reduce((a, b) => a + b[1], 0);
    let r = Math.random() * total;
    for (const [id, w] of table) {
      r -= w;
      if (r <= 0) { this.S.weather = id; return id; }
    }
    this.S.weather = 'clear';
    return 'clear';
  }

  /** Advances one day. travel=false for chore days and landmark rests. */
  advanceDay({ travel }) {
    const S = this.S;
    const today = S.day;
    const alive = this.alive();
    const n = alive.length;
    if (n === 0) return;
    const p = PACES[S.pace];
    const r = RATIONS[S.ration];
    const w = WEATHERS[S.weather];
    const scale = 0.42 + 0.58 * (n / 4);
    const messages = [];

    // --- fuel & distance ---
    let dist = 0;
    let fuelUsed = 0;
    if (travel) {
      const baseDist = p.dist * w.dist * (0.58 + S.hull * 0.0042) * (S.morale < 30 ? 0.92 : 1) * (this.hasTrait('rook') ? 1.05 : 1);
      dist = Math.round(baseDist * (0.93 + Math.random() * 0.14));
      const fuelNeed = p.fuel * (1 + (100 - S.hull) * 0.0032);
      fuelUsed = Math.min(S.fuel, fuelNeed);
      if (fuelUsed < fuelNeed - 0.001) {
        dist = Math.round(dist * Math.max(0.12, fuelUsed / fuelNeed));
        messages.push({ text: 'The cells run dry before the day does. The Mule rolls on fumes and bad language.', kind: 'warn' });
        S.morale = clamp(S.morale - 2, 0, 100);
      }
      S.fuel = clamp(S.fuel - fuelUsed, 0, 99);
      S.mile = Math.min(960, S.mile + dist);
      S.stats.miles += dist;
    } else {
      // idling still sips fuel for heat / lights
      S.fuel = clamp(S.fuel - 0.6, 0, 99);
    }

    // --- water & food ---
    const waterNeed = BASE_USE.water * p.water * w.water * scale * (travel ? 1 : 0.72);
    const foodNeed = BASE_USE.food * r.food * scale * (travel ? 1 : 0.92);
    const waterHave = S.water;
    const foodHave = S.food;
    S.water = clamp(S.water - waterNeed, 0, 99);
    S.food = clamp(S.food - foodNeed, 0, 99);
    const waterGap = Math.max(0, waterNeed - waterHave) / Math.max(0.1, waterNeed);
    const foodGap = Math.max(0, foodNeed - foodHave) / Math.max(0.1, foodNeed);

    if (waterGap > 0.02) {
      const dmg = 5 + waterGap * 11;
      this.hurtAll(dmg);
      S.morale = clamp(S.morale - 4 * waterGap, 0, 100);
      messages.push({ text: `The canteens are dry. ${waterGap > 0.7 ? 'Everyone is cracking at the lips, seeing spots.' : 'Rationing water down to the last mouthful.'}`, kind: 'bad' });
    }
    if (foodGap > 0.02) {
      const dmg = 3 + foodGap * 7;
      this.hurtAll(dmg);
      S.morale = clamp(S.morale - 3.5 * foodGap, 0, 100);
      messages.push({ text: `${foodGap > 0.7 ? 'Nobody has eaten properly in days.' : 'Rations come up short. Bellies complain louder than the engine.'}`, kind: 'bad' });
    }

    // --- status & morale drift ---
    for (const m of this.alive()) {
      if (m.status === 'sick') this.health(m, -1.3);
      else if (m.status === 'injured') this.health(m, -1.1);
      else if (m.status === 'rad') this.health(m, -1.6);
      else if (waterGap === 0 && foodGap === 0 && r === RATIONS.full && S.morale > 55) this.health(m, 0.5);
    }
    let morale = r.morale + p.morale;
    if (S.weather === 'storm') morale -= 2;
    if (S.weather === 'rain') morale -= 0.6;
    if (waterGap > 0) morale -= 2;
    if (foodGap > 0) morale -= 2;
    if (this.alive().some((m) => m.status === 'sick')) morale -= 0.8;
    if (this.S.dog) morale += 0.5;
    S.morale = clamp(S.morale + morale, 0, 100);

    // --- hull wear ---
    if (travel) {
      let wear = p.hullWear * (0.22 + w.hazard * 5.2) * (0.7 + Math.random() * 0.7);
      if (this.hasTrait('voss')) wear *= 0.78;
      if (wear > 0.15) S.hull = clamp(S.hull - wear, 0, 100);
      if (S.hull < 46 && chance(0.1 + (46 - S.hull) * 0.008)) {
        const dmg = int(2, 7);
        S.hull = clamp(S.hull - dmg, 0, 100);
        S.stats.damages += 1;
        messages.push({ text: `Something under the floorpan lets go. ${this.hasTrait('voss') ? 'Mara hears it first and is already reaching for the torch.' : 'The whole frame shudders.'}`, kind: 'warn' });
      }
    }

    // --- ambient & summary ---
    if (travel) {
      messages.unshift({
        text: `Mile ${Math.floor(S.mile)}. ${dist} miles today${fuelUsed > 0 ? `, ${fuelUsed.toFixed(1)} fuel burned` : ''}. ${WEATHERS[S.weather].label.toLowerCase()}.`,
        kind: 'daybreak',
      });
      if (chance(0.35)) messages.push({ text: pick(AMBIENT), kind: '' });
    }

    S.day += 1;

    // death / end checks
    if (this.aliveCount() === 0) {
      this.finish(false, 'The last of you stops breathing somewhere on the road. The Mule idles until the fuel runs out.');
    } else if (S.hull <= 0) {
      this.finish(false, 'The Mule gives out — a sound like a dropped toolbox, then nothing. Without wheels, the miles are just weather.');
    }

    return { messages, dist, today, ended: !!S.ended };
  }

  /* ---------- public turn actions ---------- */

  drive() {
    if (this.phase !== 'travel' || !this.S || this.S.ended) return null;
    this.rollWeather();
    const res = this.advanceDay({ travel: true });
    if (!res) return null;
    if (this.S.ended) return { messages: res.messages, ended: this.S.ended };

    const arrival = this.checkArrival();
    if (arrival) {
      this.pendingArrival = arrival;
      this.phase = 'arrival';
      this.log(`You reach ${arrival.name}.`, 'good');
      this.save();
      return { messages: res.messages, arrival: this.publicStop(arrival) };
    }

    const ev = this.maybeEvent();
    if (ev) {
      this.pendingEvent = ev;
      this.phase = 'event';
      this.log(`— ${ev.title} —`, 'event');
      this.save();
      return { messages: res.messages, event: this.eventView(ev) };
    }

    this.save();
    return { messages: res.messages };
  }

  chore(id) {
    if (this.phase !== 'travel' || !this.S || this.S.ended) return null;
    const chore = CHORES.find((c) => c.id === id);
    if (!chore) return null;
    const messages = [];
    const S = this.S;

    if (id === 'scavenge') {
      if (!this.pay({ water: 1 })) return { blocked: 'You need 1 water for the trip into the ruins.' };
      const p = PACES[S.pace];
      const loot = Math.round(int(13, 27) * (this.hasTrait('dex') ? 1.35 : 1));
      const fuel = int(0, 5);
      this.add({ scrap: loot, fuel });
      S.stats.scavenged += loot;
      messages.push({ text: `You spend the day in a collapsed mall picking copper out of the walls. +${loot} scrap${fuel ? `, +${fuel} fuel` : ''}.`, kind: 'good' });
      if (chance(0.33)) {
        const water = int(3, 6);
        this.add({ water });
        messages.push({ text: `A pipe in the ceiling still holds clean water. You fill ${water} units.`, kind: 'good' });
      }
      if (chance(0.28)) {
        const m = this.hurt(int(5, 12));
        messages.push({ text: `${m ? m.name : 'Someone'} comes back limping. ${pick(['A floor gave way.', 'Someone else was already living in there.', 'A nail through the boot.'])}`, kind: 'bad' });
      }
    } else if (id === 'forage') {
      const food = int(6, 14) + (this.hasTrait('rook') ? 2 : 0);
      const water = int(1, 4);
      this.add({ food, water });
      S.foodFound += food;
      messages.push({ text: `Rook finds a drainage cut with edible weeds and something that used to be a rabbit. +${food} rations, +${water} water.`, kind: 'good' });
      if (chance(0.2)) {
        const m = this.hurt(int(4, 10));
        messages.push({ text: `${m ? m.name : 'Someone'} gets cut open on a snare in the brush.`, kind: 'bad' });
      }
    } else if (id === 'rest') {
      const heal = 9 + (this.hasTrait('reyes') ? 6 : 0);
      this.heal(heal);
      this.add({ morale: 6 });
      messages.push({ text: `You pull off the road and let the engine cool. Everyone sleeps in a pile with the heater on low. The crew looks human again.`, kind: 'good' });
    } else if (id === 'repair') {
      if (!this.pay({ scrap: 6 })) return { blocked: 'You need 6 scrap to patch the hull.' };
      if (S.hull >= 99) return { blocked: 'The Mule is already as whole as it is ever going to be.' };
      const patch = 11 + (this.hasTrait('voss') ? 7 : 0);
      this.add({ hull: patch });
      messages.push({ text: `Mara welds a plate over the worst of it and Dex holds the light. +${patch} hull. ${S.hull > 90 ? '"Good as new," she lies.' : '"It\'ll hold."'}`, kind: 'good' });
    } else if (id === 'distill') {
      if (!this.pay({ fuel: 3 })) return { blocked: 'You need 3 fuel to run the still.' };
      const water = int(11, 17) + (S.weather === 'rain' ? 4 : 0);
      this.add({ water });
      messages.push({ text: `You run the still off the engine block. It gurgles and spits and gives up ${water} units of water that tastes like hot plastic.`, kind: 'good' });
    }

    S.stats.chores += 1;
    const res = this.advanceDay({ travel: false });
    if (res) messages.unshift(...res.messages);
    if (S.ended) { this.save(); return { messages, ended: S.ended }; }
    messages.push(...this.choreDrift(id));
    this.save();
    return { messages };
  }

  choreDrift(id) {
    const out = [];
    const roll = Math.random();
    if (roll < 0.13) {
      const m = this.alive()[Math.floor(Math.random() * this.aliveCount())];
      if (id === 'scavenge' && chance(0.5)) {
        this.add({ scrap: 8 });
        out.push({ text: 'On the way back, Dex kicks open a locker with eight more scrap in it. He is insufferable about this.', kind: 'good' });
      } else if (m) {
        this.health(m, -4, id === 'repair' ? 'injured' : 'sick');
        out.push({ text: `${m.name} picks up a cough that settles in for the night.`, kind: 'warn' });
      }
    }
    return out;
  }

  /* ---------- events ---------- */

  maybeEvent() {
    const S = this.S;
    let p = 0.5;
    if (S.pace === 'sprint') p += 0.1;
    if (S.weather === 'storm') p += 0.08;
    if (!chance(p)) return null;
    const eligible = EVENTS.filter((e) => {
      if (S.recentEvents.includes(e.id)) return false;
      if (e.id === 'fever' && this.aliveCount() < 2) return false;
      return true;
    });
    if (!eligible.length) return null;
    const total = eligible.reduce((a, e) => a + e.weight, 0);
    let r = Math.random() * total;
    let chosen = eligible[eligible.length - 1];
    for (const e of eligible) {
      r -= e.weight;
      if (r <= 0) { chosen = e; break; }
    }
    S.recentEvents.push(chosen.id);
    if (S.recentEvents.length > 6) S.recentEvents.shift();
    S.stats.events += 1;
    return chosen;
  }

  eventView(ev) {
    const g = this.context();
    const text = typeof ev.text === 'function' ? ev.text(g) : ev.text;
    const choices = ev.choices.map((c, i) => {
      let disabled = null;
      if (c.requires) disabled = c.requires(g);
      return { i, label: c.label, hint: c.hint, disabled };
    });
    return { id: ev.id, title: ev.title, kicker: ev.kicker, art: ev.art, text, choices };
  }

  context() {
    const g = {
      s: this.S,
      chance, pick, int,
      rand: Math.random,
      add: (d) => this.add(d),
      pay: (c) => this.pay(c),
      can: (c) => this.canAfford(c),
      hurt: (amt, status = 'injured', member = null) => this.hurt(amt, status, member),
      hurtAll: (amt, status) => this.hurtAll(amt, status),
      heal: (amt) => this.heal(amt),
      pickAlive: () => pick(this.alive()),
      alive: () => this.alive(),
      byId: (id) => this.byId(id),
      log: (t, k) => this.log(t, k),
      morale: (n) => this.add({ morale: n }),
      hull: (n) => this.add({ hull: n }),
      trait: (id) => this.hasTrait(id),
    };
    return g;
  }

  resolveEvent(index) {
    if (this.phase !== 'event' || !this.pendingEvent) return null;
    const ev = this.pendingEvent;
    const choice = ev.choices[index];
    if (!choice) return null;
    const g = this.context();
    if (choice.requires && choice.requires(g)) return null;
    const text = choice.run(g) || '';
    this.log(text, 'event');
    this.pendingEvent = null;
    this.phase = 'travel';
    this.pendingArrival = this.checkArrival();
    this.save();
    return { text, arrival: this.pendingArrival ? this.publicStop(this.pendingArrival) : null, ended: this.S.ended };
  }

  finishEvent() {
    if (this.pendingArrival) {
      this.phase = 'arrival';
      return { arrival: this.publicStop(this.pendingArrival) };
    }
    this.pendingArrival = null;
    this.phase = 'travel';
    return {};
  }

  publicStop(stop) {
    return {
      mile: stop.mile, name: stop.name, tag: stop.tag, sector: stop.sector,
      blurb: stop.blurb, voice: stop.voice, prices: stop.prices,
      stock: this.S.stocks[stop.mile], visited: this.S.visited.includes(stop.mile),
      final: stop.mile >= 960,
    };
  }

  checkArrival() {
    const stop = ROUTE.find((s) => s.mile > 0 && this.S.mile >= s.mile);
    if (stop) {
      this.S.mile = Math.max(this.S.mile, stop.mile);
      if (!this.S.visited.includes(stop.mile)) this.S.visited.push(stop.mile);
      return stop;
    }
    return null;
  }

  /* ---------- landmark ---------- */

  buy(item, qty) {
    const S = this.S;
    const stop = ROUTE.find((s) => s.mile === S.mile);
    if (!stop) return { ok: false, msg: 'No trading post here.' };
    const price = stop.prices[item];
    const stock = S.stocks[stop.mile][item];
    qty = Math.max(1, Math.min(99, Math.floor(qty) || 0));
    const actual = Math.min(qty, stock, Math.floor(S.scrap / price));
    if (actual <= 0) return { ok: false, msg: stock <= 0 ? 'Sold out.' : 'Not enough scrap.' };
    S.scrap -= actual * price;
    S.stocks[stop.mile][item] = stock - actual;
    this.add({ [item]: actual });
    this.log(`Bought ${actual} ${item} at ${stop.short} for ${(actual * price).toFixed(0)} scrap.`, 'good');
    this.save();
    return { ok: true, actual, cost: actual * price, stock: S.stocks[stop.mile][item] };
  }

  restAtLandmark() {
    const S = this.S;
    if (this.phase !== 'arrival') return null;
    if (S.restedAt.includes(S.mile)) return { blocked: 'You already rested here.' };
    S.restedAt.push(S.mile);
    this.heal(13);
    this.add({ morale: 5 });
    this.log('You take a room — or a corner of one — and sleep with a roof overhead. It changes very little. It changes everything.', 'good');
    const res = this.advanceDay({ travel: false });
    this.save();
    return { messages: res ? res.messages : [], ended: !!S.ended };
  }

  rumor() {
    const S = this.S;
    const stop = ROUTE.find((s) => s.mile === S.mile);
    const text = pick(ROAD_RUMORS);
    if (S.rumors[S.mile]) return { text: S.rumors[S.mile] };
    S.rumors[S.mile] = text;
    this.log(`At ${stop.short}: ${text}`, '');
    this.save();
    return { text };
  }

  leaveLandmark() {
    if (this.phase !== 'arrival') return null;
    if (this.S.mile >= 960) return { ended: this.finish(true) };
    this.pendingArrival = null;
    this.phase = 'travel';
    this.log('The Mule pulls back onto the road.', '');
    this.save();
    return {};
  }

  /* ---------- endings ---------- */

  finish(victory, reason) {
    const S = this.S;
    if (!S || S.ended) return S ? S.ended : null;
    const survivors = this.alive();
    const score = victory
      ? Math.round((survivors.length * 1000) + Math.max(0, 900 - S.day) * 20 + S.morale * 8 + Math.min(300, S.scrap))
      : 0;
    const grade = !victory ? 'F' : score > 5600 ? 'S' : score > 4700 ? 'A' : score > 3800 ? 'B' : score > 3000 ? 'C' : 'D';
    const lost = S.party.filter((p) => !p.alive);
    S.ended = {
      victory, reason: reason || '', score, grade,
      survivors: survivors.map((p) => ({ name: p.name, role: p.role, initials: p.initials, health: Math.round(p.health), tone: p.tone })),
      lost: lost.map((p) => ({ name: p.name, role: p.role, initials: p.initials, tone: p.tone, cause: p.cause })),
      day: S.day, mile: Math.round(S.mile), loot: S.scrapEarned, events: S.stats.events,
    };
    this.phase = 'ended';
    this.clearSave();
    return S.ended;
  }

  endIfNeeded() {
    if (!this.S || this.S.ended) return this.S?.ended || null;
    if (this.aliveCount() === 0) return this.finish(false, 'The last of you stops breathing somewhere on the road. The Mule idles until the fuel runs out.');
    if (this.S.hull <= 0) return this.finish(false, 'The Mule gives out — a sound like a dropped toolbox, then nothing. Without wheels, the miles are just weather.');
    if (this.S.mile >= 960) return this.finish(true);
    return null;
  }
}

/* ASH TRAIL — interface, rendering, interactions */

import { WastelandScene } from './scene.js';
import { Game } from './engine.js';
import { ROUTE, CHORES, PACES, RATIONS, WEATHERS, BASE_USE, CREW_TEMPLATES } from './data.js';

const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const icon = (id) => `<svg aria-hidden="true"><use href="#${id}"/></svg>`;
const money = (n) => Math.round(n);

const game = new Game();
const ui = {
  scene: null,
  titleScene: null,
  busy: false,
  muted: false,
  logKey: '',
  shopQty: {},
  started: false,
  modalMode: null,
  currentEvent: null,
  currentArrival: null,
};

/* ============================== audio ============================== */

let audioCtx = null;
function ensureAudio() {
  if (audioCtx) return audioCtx;
  const Ctor = window.AudioContext || window.webkitAudioContext;
  if (!Ctor) return null;
  try { audioCtx = new Ctor(); } catch { return null; }
  return audioCtx;
}

function sound(name) {
  if (ui.muted) return;
  const ctx = ensureAudio();
  if (!ctx) return;
  if (ctx.state === 'suspended') ctx.resume();
  const now = ctx.currentTime;
  const master = ctx.createGain();
  master.gain.value = 0.045;
  master.connect(ctx.destination);
  const notes = {
    click: [[300, 0.035, 'square', 0.4]],
    good: [[440, 0.08, 'sine', 0.5], [660, 0.12, 'sine', 0.4]],
    bad: [[150, 0.16, 'sawtooth', 0.35], [96, 0.24, 'sawtooth', 0.3]],
    drive: [[110, 0.35, 'sawtooth', 0.22], [70, 0.5, 'sawtooth', 0.16]],
    death: [[90, 0.5, 'sine', 0.4], [60, 0.9, 'sine', 0.3]],
    win: [[392, 0.18, 'triangle', 0.4], [523, 0.18, 'triangle', 0.4], [659, 0.42, 'triangle', 0.35]],
  }[name];
  if (!notes) return;
  notes.forEach(([freq, dur, type, vol], i) => {
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, now + i * 0.01);
    if (name === 'drive') o.frequency.exponentialRampToValueAtTime(freq * 0.6, now + dur);
    g.gain.setValueAtTime(0.0001, now);
    g.gain.exponentialRampToValueAtTime(vol, now + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    o.connect(g).connect(master);
    o.start(now);
    o.stop(now + dur + 0.02);
  });
}

function loadMuted() {
  try { return localStorage.getItem('ashtrail-muted') === '1'; } catch { return false; }
}

function setMuted(m) {
  ui.muted = m;
  try { localStorage.setItem('ashtrail-muted', m ? '1' : '0'); } catch { /* ignore */ }
  const btn = $('#btn-sound');
  if (btn) {
    btn.innerHTML = m ? icon('i-mute') : icon('i-volume');
    btn.setAttribute('aria-label', m ? 'Enable sound' : 'Mute sound');
  }
}

/* ============================== helpers ============================== */

function toast(msg, kind = '') {
  const layer = $('#toast-layer');
  const el = document.createElement('div');
  el.className = `toast ${kind}`;
  el.textContent = msg;
  layer.appendChild(el);
  setTimeout(() => {
    el.style.transition = 'opacity .3s, transform .3s';
    el.style.opacity = '0';
    el.style.transform = 'translateY(6px)';
    setTimeout(() => el.remove(), 320);
  }, 2400);
}

function formatDay(d) { return String(d).padStart(2, '0'); }

function memberStatus(p) {
  if (!p.alive) return { label: 'dead', cls: 'dead' };
  if (p.status === 'sick') return { label: 'sick', cls: 'sick' };
  if (p.status === 'injured') return { label: 'injured', cls: 'injured' };
  if (p.status === 'rad') return { label: 'rad', cls: 'rad' };
  return { label: 'stable', cls: '' };
}

function healthTone(v) {
  if (v > 65) return '#78d7cb';
  if (v > 35) return '#ffb454';
  return '#ff5a4e';
}

function nextStopName() {
  const stop = game.nextStop();
  return stop ? stop.name : 'EDEN-9';
}

function paceEstimate() {
  if (!game.S) return { dist: 0, fuel: 0 };
  const p = PACES[game.S.pace];
  const w = WEATHERS[game.S.weather];
  const dist = Math.round(p.dist * w.dist * (0.58 + game.S.hull * 0.0042));
  const fuel = p.fuel * (1 + (100 - game.S.hull) * 0.0032);
  const scale = 0.42 + 0.58 * (game.aliveCount() / 4);
  const water = BASE_USE.water * p.water * w.water * scale;
  return { dist, fuel, water };
}

/* ============================== start screen ============================== */

function renderStartRoster() {
  const el = $('#start-roster');
  el.innerHTML = CREW_TEMPLATES.map((c) => `
    <div class="roster-card">
      <div class="av" data-tone="${c.tone}">${c.initials}</div>
      <b>${c.name}</b>
      <em>${c.role}</em>
    </div>`).join('');
}

function refreshResume() {
  const btn = $('#btn-resume');
  const saved = game.peekSave();
  if (!saved) { btn.classList.add('hidden'); return; }
  btn.classList.remove('hidden');
  btn.textContent = `Resume — day ${String(saved.day).padStart(2, '0')}, mile ${Math.round(saved.mile)}`;
}

function showStart() {
  $('#screen-game').classList.add('hidden');
  $('#screen-start').classList.remove('hidden');
  closeModal(true);
  refreshResume();
  if (!ui.titleScene) {
    const c = $('#title-scene');
    if (c) {
      ui.titleScene = new WastelandScene(c, { title: true });
      ui.titleScene.state.weather = 'dusk';
      ui.titleScene.setState({ mile: 120, weather: 'haze', hull: 62, progress: 0.12 });
      ui.titleScene.start();
    }
  } else {
    ui.titleScene.start();
  }
  if (ui.scene) ui.scene.stop();
  document.title = 'ASH TRAIL — Eden-9';
}

function beginGame(resume = false) {
  const state = resume ? game.load() : game.newGame();
  if (!state) return;
  $('#screen-start').classList.add('hidden');
  $('#screen-game').classList.remove('hidden');
  if (ui.titleScene) ui.titleScene.stop();
  ui.started = true;
  ui.shopQty = {};
  if (!ui.scene) {
    ui.scene = new WastelandScene($('#scene'));
    ui.scene.setState({ mile: game.S.mile, weather: game.S.weather, hull: game.S.hull, speed: 0.55 });
    ui.scene.start();
  }
  ui.scene.setState({ mile: game.S.mile, weather: game.S.weather, hull: game.S.hull });
  ui.scene.setSpeed(paceSpeed());
  render();
  if (!resume) {
    toast('The gate closes. Nine hundred sixty miles to go.', '');
    sound('drive');
  }
  document.title = 'ASH TRAIL — day ' + game.S.day;
}

/* ============================== game render ============================== */

function paceSpeed() {
  const p = game.S?.pace || 'steady';
  return p === 'crawl' ? 0.32 : p === 'sprint' ? 0.95 : 0.58;
}

function render() {
  const S = game.S;
  if (!S) return;
  renderHud(S);
  renderSupplies(S);
  renderBars(S);
  renderCrew(S);
  renderLog(S);
  renderControls(S);
  if (ui.scene) {
    ui.scene.setState({
      mile: S.mile, weather: S.weather, hull: S.hull, progress: S.mile / 960,
      pace: S.pace,
    });
    ui.scene.setSpeed(paceSpeed());
  }
}

function renderHud(S) {
  $('#hud-day').textContent = formatDay(S.day);
  $('#hud-mile').textContent = String(Math.round(S.mile)).padStart(3, '0');
  $('#hud-crew').textContent = game.aliveCount();
  const stop = game.nextStop();
  $('#hud-sector').textContent = stop ? `${stop.name} · ${Math.max(0, Math.round(stop.mile - S.mile))} MI` : 'EDEN-9';
  const w = WEATHERS[S.weather] || WEATHERS.clear;
  $('#hud-weather').innerHTML = `${icon(w.icon)}<span>${w.label}</span>`;
  const pct = clamp((S.mile / 960) * 100, 0, 100);
  $('#progress-fill').style.width = pct + '%';
  $('#progress-marker').style.left = pct + '%';
  const ticks = $('#progress-ticks');
  if (!ticks.dataset.ready) {
    ticks.innerHTML = ROUTE.filter((s) => s.mile > 0 && s.mile < 960)
      .map((s) => `<i style="left:${(s.mile / 960) * 100}%"></i>`).join('');
    ticks.dataset.ready = '1';
  }
}

function renderSupplies(S) {
  const items = [
    { id: 'water', k: 'Water', v: Math.floor(S.water), icon: 'i-water', low: 14, crit: 6, unit: 'u' },
    { id: 'food', k: 'Rations', v: Math.floor(S.food), icon: 'i-food', low: 12, crit: 5, unit: 'u' },
    { id: 'fuel', k: 'Fuel', v: Math.floor(S.fuel), icon: 'i-fuel', low: 10, crit: 4, unit: 'u' },
    { id: 'meds', k: 'Meds', v: S.meds, icon: 'i-meds', low: 1, crit: 0, unit: '' },
    { id: 'scrap', k: 'Scrap', v: S.scrap, icon: 'i-scrap', low: 20, crit: 6, unit: '' },
    { id: 'hull', k: 'Hull', v: Math.round(S.hull), icon: 'i-hull', low: 40, crit: 18, unit: '%' },
  ];
  $('#supply-grid').innerHTML = items.map((it) => {
    let cls = '';
    if (it.v <= it.crit) cls = 'crit';
    else if (it.v <= it.low) cls = 'low';
    return `<div class="supply ${cls}" title="${it.k}">
      <div class="supply-top">${icon(it.icon)}<span class="supply-k">${it.k}</span></div>
      <div class="supply-v">${it.v}${it.unit ? `<small>${it.unit}</small>` : ''}</div>
    </div>`;
  }).join('');
  const dist = game.nextStop() ? Math.max(0, Math.round(game.nextStop().mile - S.mile)) : 0;
  $('#stores-meta').textContent = `${dist} mi to ${game.nextStop() ? game.nextStop().short : 'Eden-9'}`;
}

function renderBars(S) {
  const rows = [
    { k: 'Hull', v: S.hull, tone: S.hull > 55 ? '#c9a06a' : S.hull > 25 ? '#ff8a45' : '#ff5a4e', val: Math.round(S.hull) },
    { k: 'Morale', v: S.morale, tone: S.morale > 55 ? '#78d7cb' : S.morale > 28 ? '#ffb454' : '#ff5a4e', val: Math.round(S.morale) },
  ];
  $('#bars').innerHTML = rows.map((r) => `
    <div class="bar-row">
      <span class="bar-k">${r.k}</span>
      <div class="bar-track"><div class="bar-fill" style="width:${clamp(r.v, 0, 100)}%;background:${r.tone}"></div></div>
      <span class="bar-val">${r.val}</span>
    </div>`).join('');
}

function renderCrew(S) {
  $('#crew-grid').innerHTML = S.party.map((p) => {
    const st = memberStatus(p);
    const tone = healthTone(p.health);
    return `
      <div class="crew ${p.alive ? '' : 'dead'}">
        <div class="crew-top">
          <div class="av" data-tone="${p.tone}">${p.alive ? p.initials : '—'}</div>
          <div style="min-width:0">
            <div class="crew-name">${p.name}</div>
            <div class="crew-status ${st.cls}">${p.alive ? `${p.role} · ${st.label}` : 'dead'}</div>
          </div>
        </div>
        <div class="health">
          <div class="health-track"><div class="health-fill" style="width:${p.health}%;background:${tone}"></div></div>
          <span class="health-num">${Math.round(p.health)}</span>
        </div>
      </div>`;
  }).join('');
}

function renderLog(S, force = false) {
  const log = $('#log');
  const key = `${S.log.length}:${S.day}:${game.phase}`;
  if (!force && key === ui.logKey) return;
  ui.logKey = key;
  const nearBottom = log.scrollHeight - log.scrollTop - log.clientHeight < 70;
  log.innerHTML = S.log.map((e) => `
    <div class="entry ${e.kind || ''}">
      <span class="d">D${formatDay(e.day)}</span>
      <div>${e.text}</div>
    </div>`).join('');
  if (nearBottom || force) log.scrollTop = log.scrollHeight;
  $('#log-meta').textContent = `day ${formatDay(S.day)}`;
}

function renderControls(S) {
  const locked = game.phase !== 'travel' || !!S.ended;
  $$('#pace-group button').forEach((b) => {
    const on = b.dataset.pace === S.pace;
    b.classList.toggle('on', on);
    b.disabled = locked;
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
  $$('#ration-group button').forEach((b) => {
    const on = b.dataset.ration === S.ration;
    b.classList.toggle('on', on);
    b.disabled = locked;
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
  $('#pace-note').textContent = PACES[S.pace].note;
  $('#ration-note').textContent = RATIONS[S.ration].note;

  const est = paceEstimate();
  $('#drive-sub').textContent = `~${est.dist} mi · ${est.fuel.toFixed(1)} fuel · ${est.water.toFixed(1)} water`;
  const drive = $('#btn-drive');
  drive.disabled = locked;

  const costs = { scavenge: { water: 1 }, repair: { scrap: 6 }, distill: { fuel: 3 }, forage: {}, rest: {} };
  $('#action-grid').innerHTML = CHORES.map((c, i) => {
    let disabled = locked;
    let reason = '';
    if (S.fuel <= 0 && c.id === 'distill') reason = 'No fuel';
    if (!game.canAfford(costs[c.id] || {})) { disabled = true; reason = 'Not enough supplies'; }
    if (c.id === 'repair' && S.hull >= 99) { disabled = true; reason = 'Hull intact'; }
    return `<button class="action" data-chore="${c.id}" ${disabled ? 'disabled' : ''}
        title="${c.cost}${reason ? ' — ' + reason : ''}">
      <b>${c.label}</b><span>${c.sub}</span>
    </button>`;
  }).join('');
  $$('#action-grid .action').forEach((b) => { b.dataset.index = CHORES.findIndex((c) => c.id === b.dataset.chore) + 1; });
}

/* ============================== wiring ============================== */

function guard(fn) {
  if (ui.busy) return;
  ui.busy = true;
  try { fn(); } finally { setTimeout(() => { ui.busy = false; }, 120); }
}

function onDrive() {
  if (!game.S || game.phase !== 'travel' || game.S.ended) return;
  guard(() => {
    const res = game.drive();
    if (!res) return;
    render();
    if (res.ended) { showEnding(res.ended); return; }
    if (ui.scene) { ui.scene.setSpeed(1.25); setTimeout(() => ui.scene && ui.scene.setSpeed(paceSpeed()), 900); }
    sound('drive');
    if (res.arrival) { showArrival(res.arrival); return; }
    if (res.event) { showEvent(res.event); return; }
    if (game.S.ended) showEnding(game.S.ended);
  });
}

function onChore(id) {
  if (!game.S || game.phase !== 'travel' || game.S.ended) return;
  guard(() => {
    const res = game.chore(id);
    if (!res) return;
    render();
    if (res.blocked) { toast(res.blocked, 'bad'); sound('bad'); return; }
    sound(id === 'rest' ? 'good' : 'click');
    if (res.ended) { showEnding(res.ended); return; }
    if (res.event) { showEvent(res.event); return; }
    if (game.S.ended) showEnding(game.S.ended);
  });
}

function setPace(pace) {
  if (!game.S || game.phase !== 'travel') return;
  game.S.pace = pace;
  render();
  sound('click');
}

function setRation(ration) {
  if (!game.S || game.phase !== 'travel') return;
  game.S.ration = ration;
  render();
  sound('click');
}

export function boot() {
  ui.muted = loadMuted();
  setMuted(ui.muted);
  renderStartRoster();
  refreshResume();
  showStart();

  $('#btn-start').addEventListener('click', () => { ensureAudio(); sound('click'); beginGame(false); });
  $('#btn-resume').addEventListener('click', () => { ensureAudio(); sound('click'); beginGame(true); });
  $('#btn-sound').addEventListener('click', () => { setMuted(!ui.muted); if (!ui.muted) sound('good'); });
  $('#btn-quit').addEventListener('click', () => { sound('click'); showQuit(); });
  $('#btn-drive').addEventListener('click', onDrive);

  $('#pace-group').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-pace]');
    if (b) setPace(b.dataset.pace);
  });
  $('#ration-group').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-ration]');
    if (b) setRation(b.dataset.ration);
  });
  $('#action-grid').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-chore]');
    if (b && !b.disabled) onChore(b.dataset.chore);
  });

  document.addEventListener('keydown', (e) => {
    if (e.target.matches('input, textarea')) return;
    if (!$('#modal-layer').classList.contains('hidden')) {
      if (e.key === 'Enter' || e.key === ' ') {
        const primary = $('#modal-card [data-enter]');
        if (primary && !primary.disabled) { e.preventDefault(); primary.click(); }
      }
      return;
    }
    if ($('#screen-game').classList.contains('hidden')) {
      if (e.key === 'Enter') $('#btn-start').click();
      return;
    }
    if (e.code === 'Space') { e.preventDefault(); if (!$('#btn-drive').disabled) onDrive(); }
    else if (/^[1-5]$/.test(e.key)) {
      const chore = CHORES[Number(e.key) - 1];
      if (chore) onChore(chore.id);
    }
  });

  document.addEventListener('visibilitychange', () => {
    if (!ui.scene) return;
    if (document.hidden) ui.scene.stop();
    else if (!$('#screen-game').classList.contains('hidden')) ui.scene.start();
  });

  window.addEventListener('beforeunload', () => { if (game.S && !game.S.ended) game.save(); });

  // test hook (harmless in production)
  window.__ASH = { game, render, boot };

  /* PART2 */
}

input.newString:
  window.__ASH = { game, render, boot };
}

/* ============================== modals ============================== */

function openModal(html, mode) {
  ui.modalMode = mode;
  const layer = $('#modal-layer');
  const card = $('#modal-card');
  card.innerHTML = html;
  layer.classList.remove('hidden');
  document.body.classList.add('modal-open');
  requestAnimationFrame(() => {
    card.scrollTop = 0;
    const focusable = card.querySelector('button:not([disabled])');
    if (focusable && window.innerWidth > 700) focusable.focus({ preventScroll: true });
  });
}

function closeModal(silent = false) {
  $('#modal-layer').classList.add('hidden');
  $('#modal-card').innerHTML = '';
  document.body.classList.remove('modal-open');
  ui.modalMode = null;
  if (!silent) sound('click');
}

function modalVisual(iconName, tag) {
  return `<div class="modal-visual">
    <div class="mv-stripes"></div>
    <div class="mv-icon">${icon(iconName)}</div>
    <span class="tag">${tag}</span>
  </div>`;
}

/* ============================== events ============================== */

function showEvent(view) {
  ui.currentEvent = view;
  const buttons = view.choices.map((c) => `
    <button class="choice" data-choice="${c.i}" ${c.disabled ? 'disabled' : ''} ${c.i === 0 ? 'data-enter="1"' : ''}>
      <b><i>${String(c.i + 1).padStart(2, '0')}</i>${c.label}</b>
      <span>${c.disabled || c.hint}</span>
    </button>`).join('');
  openModal(`
    <div class="modal-kicker">${view.kicker} · DAY ${formatDay(game.S.day)}</div>
    <h3>${view.title}</h3>
    ${modalVisual(artIcon(view.art), 'FIELD NOTE · ' + view.id.toUpperCase())}
    <p class="modal-text">${view.text}</p>
    <div class="modal-choices">${buttons}</div>
  `, 'event');
  sound('bad');
  if (ui.scene) ui.scene.kick(0.8);
}

function artIcon(kind) {
  return {
    raider: 'i-hull', rain: 'i-rain', drone: 'i-signal', family: 'i-morale',
    greenhouse: 'i-food', dog: 'i-morale', rad: 'i-storm', wreck: 'i-hull',
    medic: 'i-meds', terminal: 'i-scrap', cult: 'i-flag', bridge: 'i-hull',
    shrine: 'i-flag', water: 'i-water', signal: 'i-signal',
  }[kind] || 'i-dust';
}

function chooseEvent(index) {
  const res = game.resolveEvent(index);
  if (!res) return;
  render();
  if (ui.scene) ui.scene.kick(1.2);
  const ended = game.endIfNeeded();
  if (ended) { showEnding(ended); return; }
  ui.pendingOutcomeArrival = res.arrival;
  const arrival = res.arrival;
  openModal(`
    <div class="modal-kicker">${arrival ? 'ARRIVAL' : 'CONSEQUENCE'}</div>
    <div class="modal-outcome"><p>${res.text}</p></div>
    ${arrival ? `<p class="modal-text">Through the dust: <strong>${arrival.name}</strong>. ${arrival.mile === 960 ? 'The last mile.' : 'A place to trade, rest, and hear a lie or two.'}</p>` : ''}
    <div class="modal-actions">
      <button class="btn btn-primary" data-act="outcome-continue" data-enter="1">${arrival ? 'Approach the stop' : 'Back on the road'}</button>
    </div>
  `, 'outcome');
  sound('click');
}

function outcomeContinue() {
  const fin = game.finishEvent();
  render();
  if (fin.arrival) { showArrival(fin.arrival); return; }
  closeModal();
}

/* ============================== endings ============================== */

function showEnding(end) {
  const winners = end.survivors;
  const lost = end.lost;
  const n = winners.length;
  const victory = end.victory;
  let title;
  let copy;
  if (victory) {
    title = n === 4 ? 'All four of you walk in.' : n === 3 ? 'Three of you walk in.' : n === 2 ? 'Two of you walk in.' : n === 1 ? 'One of you walks in.' : 'The gate opens on an empty crawler.';
    copy = n === 4
      ? 'The guard counts four and steps aside. Behind the fence there is grass, and a woman with a clipboard, and a sky the color of clean water. Nobody says anything for a long time.'
      : `The guard counts ${n} and does not ask about the seats that are empty. Eden-9 takes you in. The gate closes behind the Mule, and for the first time in nine hundred miles, nothing is following.`;
  } else {
    title = 'The road keeps what it takes.';
    copy = end.reason || 'Somewhere past the last mile marker, the Mule stops. The dust fills the seats. Eden-9 stays a rumor.';
  }

  const crewRows = [
    ...winners.map((p) => `<div class="epitaph-row"><div class="av" data-tone="${p.tone}">${p.initials}</div><span>${p.name}</span><span class="why" style="color:var(--green)">made it · ${p.health}hp</span></div>`),
    ...lost.map((p) => `<div class="epitaph-row gone"><div class="av" data-tone="${p.tone}">${p.initials}</div><span>${p.name}</span><span class="why">lost</span></div>`),
  ].join('');

  openModal(`
    <div class="end-flag" style="color:${victory ? 'var(--green)' : 'var(--red)'}">${victory ? '● RUN COMPLETE — EDEN-9' : '● RUN TERMINATED'}</div>
    <h3>${title}</h3>
    <p class="modal-text">${copy}</p>
    <div class="epitaph">${crewRows}</div>
    <div class="stats">
      <div class="stat-cell"><div class="k">Days</div><div class="v">${end.day}</div></div>
      <div class="stat-cell"><div class="k">Miles</div><div class="v">${end.mile}<small>/960</small></div></div>
      <div class="stat-cell"><div class="k">Survivors</div><div class="v">${n}<small>/4</small></div></div>
      <div class="stat-cell"><div class="k">Score</div><div class="v">${end.score}</div></div>
    </div>
    <p class="end-note">${victory ? `Grade <strong style="color:var(--amber)">${end.grade}</strong>. ${end.day} days on the road. ${end.events} encounters. ${money(end.loot)} scrap scavenged from the corpse of the world.` : 'The trail is long. Try again with more water and fewer heroics.'}</p>
    <div class="modal-actions">
      <button class="btn btn-primary" data-act="new-run" data-enter="1">Run it again</button>
      <button class="btn" data-act="title">Return to title</button>
    </div>
  `, 'ending');
  sound(victory ? 'win' : 'death');
}

/* ============================== confirm quit ============================== */

function showQuit() {
  openModal(`
    <div class="modal-kicker">PAUSE</div>
    <h3>Abandon the run?</h3>
    <p class="modal-text">The crew does not get a second crawler. All progress on this run will be lost.</p>
    <div class="modal-actions">
      <button class="btn btn-primary" data-act="quit-cancel" data-enter="1">Keep driving</button>
      <button class="btn" data-act="quit-confirm" style="color:var(--rust);border-color:rgba(255,107,53,.4)">Abandon run</button>
    </div>
  `, 'quit');
}

/* ============================== boot call ============================== */

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

